import pdfMake from 'pdfmake/build/pdfmake';
import pdfFonts from 'pdfmake/build/vfs_fonts';
import * as XLSX from 'xlsx-js-style';
import { buildStatementAOrderPdfDoc } from '../templates/statementAOrderPdf';
import { buildCourtOrderPdfDoc } from '../templates/courtOrderPdf';
import { applyPenaltyStyles, buildPenaltyRows } from '../templates/penaltyXlsx';

pdfMake.addVirtualFileSystem(pdfFonts);

function downloadPdf(docDefinition, filename) {
  pdfMake.createPdf(docDefinition).download(filename);
}

export function downloadStatementAOrderPdf(form) {
  const title = 'Заявление о вынесении судебного приказа';
  downloadPdf(buildStatementAOrderPdfDoc(form), `${title}.pdf`);
}

export function downloadCourtOrderPdf(form) {
  const title = 'СУДЕБНЫЙ ПРИКАЗ';
  downloadPdf(buildCourtOrderPdfDoc(form), `${title}.pdf`);
}

export function downloadPenaltyXlsx(form) {
  const title = 'Расчет неустойки';
  const penalty = buildPenaltyRows(form);
  const worksheet = XLSX.utils.aoa_to_sheet(penalty.rows);
  worksheet['!merges'] = penalty.merges;
  worksheet['!cols'] = penalty.cols;
  applyPenaltyStyles(XLSX, worksheet, penalty);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, 'расчет');
  XLSX.writeFile(workbook, `${title}.xlsx`);
}
