const PLACEHOLDER_COLOR = '#C00000';

function label(text) {
  return { text };
}

function placeholder(text) {
  return { text, italics: true, color: PLACEHOLDER_COLOR };
}

function plain(text) {
  return { text };
}

function field(value, placeholderText) {
  return value ? plain(value) : placeholder(placeholderText);
}

function headerLine(children) {
  return { text: children, alignment: 'right' };
}

function bodyParagraph(children) {
  return { text: children, alignment: 'justify', margin: [24, 0, 0, 8] };
}

export function buildStatementAOrderPdfDoc(form = {}) {
  const claimant = form.claimant || {};
  const debtor = (form.debtors && form.debtors[0]) || {};
  const signerFio = form.signer && form.signer.fio;

  const content = [
    headerLine([label('Мировому судье судебного участка')]),
    headerLine([placeholder('название участка')]),
    headerLine([placeholder('+ его адрес')]),
    headerLine([plain(' ')]),
    headerLine([label('Взыскатель: '), placeholder('наименование')]),
    headerLine([plain('ИНН '), field(claimant.inn, 'номер')]),
    headerLine([field(claimant.address, 'адрес')]),
    headerLine([plain(' ')]),
    headerLine([label('реквизиты счета:')]),
    headerLine([plain('р/с '), placeholder('номер')]),
    headerLine([placeholder('банк')]),
    headerLine([plain('БИК '), placeholder('номер')]),
    headerLine([plain('кор/с '), placeholder('номер')]),
    headerLine([plain(' ')]),
    headerLine([label('Должник: '), field(debtor.fio, 'ФИО')]),
    headerLine([plain('родился (ась) '), field(debtor.birthday, 'дата рожд.'), plain(',')]),
    headerLine([field(debtor.birthplace, 'место рождения')]),
    headerLine([field(debtor.inn, 'ИНН')]),
    headerLine([field(debtor.address, 'адрес')]),

    {
      text: 'Заявление о вынесении судебного приказа',
      alignment: 'center',
      bold: true,
      margin: [0, 24, 0, 24],
    },

    bodyParagraph([
      placeholder('такая-то'),
      plain(' исполняет обязанности по управлению и текущему ремонту в отношении многоквартирного дома по адресу: '),
      placeholder('адрес'),
      plain('.'),
    ]),
    bodyParagraph([
      placeholder('такой-то'),
      plain(' является собственником квартиры '),
      placeholder('номер'),
      plain(' в этом доме.'),
    ]),
    bodyParagraph([plain('Совместно с ним зарегистрированы совершеннолетние '), placeholder('такие-то'), plain('.')]),
    bodyParagraph([
      plain(
        'На основании ч. 2 ст. 30, ч. 2 ст. 31 ЖК РФ собственник вправе вселить в свое жилое помещение других граждан, являющихся членами его семьи.'
      ),
    ]),
    bodyParagraph([
      plain(
        'В связи с чем факт их совместной регистрации с собственником указывает на принадлежность их к семье собственника спорной квартиры.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Согласно ч. 1 ст. 155 ЖК РФ плата за жилое помещение и коммунальные услуги вносится ежемесячно до пятнадцатого числа месяца, следующего за истекшим месяцем.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Данная плата для собственника включает в себя: 1) плату за содержание жилого помещения, 2) взнос на капитальный ремонт, 3) плату за коммунальные услуги (ч. 2 ст. 154 ЖК РФ).'
      ),
    ]),
    bodyParagraph([
      plain(
        'Дееспособные и ограниченные в дееспособности члены семьи собственника несут солидарную с собственником обязанность по своевременному внесению платы за жилое помещение и коммунальные услуги (ч. 3 ст. 31 ЖК РФ + п. 1 ст. 21 ГК РФ).'
      ),
    ]),
    bodyParagraph([
      plain(
        'При солидарной обязанности должников кредитор вправе требовать исполнения как от всех должников совместно, так и от любого из них в отдельности, притом как полностью, так и в части долга (п. 1 ст. 323 ГК РФ).'
      ),
    ]),
    bodyParagraph([
      plain('Как следует из выкопировки из лицевого счета, по квартире '),
      placeholder('номер'),
      plain(' числится задолженность за услуги по управлению и текущему ремонту общего имущества в размере '),
      placeholder('сумма'),
      plain(' руб. (за '),
      placeholder('такие-то периоды'),
      plain(')'),
    ]),
    bodyParagraph([
      plain(
        'В связи с чем своевременная оплата такой задолженности является солидарной обязанностью собственника и совершеннолетних членов его семьи.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Поскольку данная задолженность ими просрочена, частью 14 статьи 155 ЖК РФ для собственника и совершеннолетних членов его семьи, несвоевременно и (или) не полностью внесших плату за жилое помещение и коммунальные услуги, предусмотрена законная пеня в размере 1/300 ключевой ставки Банка России от невыплаченной в срок суммы за каждый день просрочки, начиная с 31 дня, следующего за днем наступления установленного срока оплаты, по день фактической оплаты.'
      ),
    ]),
    bodyParagraph([
      plain('По расчету взыскателя (прилагается) сумма такой пени составляет '),
      placeholder('размер'),
      plain(' руб.'),
    ]),
    bodyParagraph([
      plain(
        'В соответствии с абз. 2 п. 5 постановления Пленума Верховного Суда РФ от 21.01.2016 № 1, если лица, не в пользу которых принят судебный акт, являются солидарными должниками, судебные издержки возмещаются указанными лицами в солидарном порядке.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Исходя из этого госпошлина за предъявление одним кредитором к нескольким солидарным должникам требований о взыскании общей задолженности и пени уплачивается как за одно требование, т.к. обязательство для таких должников перед кредитором является единым (п. 1 ст. 323 ГК РФ).'
      ),
    ]),
    bodyParagraph([plain('На основании изложенного, а также ст. 121, 122 ГПК РФ,')]),

    { text: 'ПРОШУ:', alignment: 'center', bold: true, margin: [0, 12, 0, 12] },

    bodyParagraph([
      label('- вынести судебный приказ о взыскании'),
      plain(' в солидарном порядке с '),
      placeholder('таких-то через запятую – ФИО полностью'),
      plain(' '),
      label('задолженности'),
      plain(' за содержание жилого помещения в размере '),
      placeholder('сумма'),
      plain(' руб., пени в сумме '),
      placeholder('размер'),
      plain(' руб., '),
      label('расходов'),
      plain(' по уплате госпошлины в размере '),
      label('2 000'),
      plain(' руб.'),
    ]),

    { text: 'Приложения:', margin: [0, 12, 0, 4] },
    { text: '1) почтовая квитанция о направлении заявления в адрес должников,' },
    { text: [plain('2) доказательства уплаты госпошлины в размере '), label('2 000'), plain(' руб.,')] },
    { text: '3) копия лицевого счета на спорную квартиру,' },
    { text: '4) расчет пени,' },
    { text: '5) копия справки о лицах, зарегистрированных в спорной квартире,' },
    { text: '6) копия доверенности представителя.' },

    { text: [field(signerFio, 'ФИО подписанта')], margin: [0, 24, 0, 0] },
  ];

  return {
    content,
    defaultStyle: { fontSize: 11 },
    pageMargins: [56, 56, 56, 56],
  };
}
